"""Original ALLIM youth curriculum. Existing alphabet lessons remain the source of stage 1."""
from pathlib import Path
import copy
import importlib.util

BASE = Path(__file__).resolve().parents[1] / 'course_01_letters' / 'content.py'
spec = importlib.util.spec_from_file_location('allim_letters', BASE)
letters = importlib.util.module_from_spec(spec)
spec.loader.exec_module(letters)


def question(prompt, options, answer, explanation, hint):
    return dict(prompt=prompt, options=options, answer=answer, explanation=explanation, hint=hint)


def lesson(key, title, goal, explanation, example, practice, teacher, questions, *, reference=None):
    return dict(id=key, title=title, minutes=12, goal=goal,
        body='\n\n'.join(['## Что получится\n'+goal, '## Разбираемся\n'+explanation,
            '## Учебный пример — не цитата из Корана\n<div dir="rtl" lang="ar" style="font-size:2rem;line-height:2.1;text-align:center">'+example+'</div>',
            '## Попробуй\n'+'\n'.join(str(i+1)+'. '+v for i,v in enumerate(practice)),
            '## Вспомни завтра\nЗакрой правило и объясни его на одном примере. Если не получилось, открой подсказку, разберись и попробуй снова. Это учебный приём, а не религиозное предписание.']),
        kids='Работай по одному примеру. После трёх примеров сделай короткую паузу. Объясни взрослому, какой знак помог тебе выбрать ответ.',
        teens='Сначала назови правило, затем примени его к новому примеру. Отметь, что ещё требует проверки преподавателем.',
        instructor_notes=teacher+'\nПроверяйте отдельно: узнавание знака; применение правила; чтение вслух. Тест подтверждает только первые два пункта. Не ставьте оценку произношению по письменному ответу.',
        questions=questions, practice=practice, reference=reference, include_in_preview=0)

